#include <pybind11/pybind11.h>
#include <torch/extension.h>
#include "acl/acl.h"
#include "torch_npu/csrc/core/npu/NPUStream.h"
#include "xent_tiling.h"
extern "C" void xent_do_fp16(uint32_t,void*,uint8_t*,uint8_t*,uint8_t*,uint8_t*);
namespace xent_ext {
using LF=void(*)(uint32_t,void*,uint8_t*,uint8_t*,uint8_t*,uint8_t*);
pybind11::tuple run_cross_entropy_loss(const at::Tensor &x, const at::Tensor &target) {
    TORCH_CHECK(x.dim()==2,"x must be [M,V]"); TORCH_CHECK(x.scalar_type()==at::kHalf,"fp16 only");
    TORCH_CHECK(target.dim()==1,"target must be [M]"); TORCH_CHECK(x.is_contiguous(),"must be contiguous");
    const auto M=static_cast<int32_t>(x.sizes()[0]), V=static_cast<int32_t>(x.sizes()[1]);
    auto tgt = target.to(at::kInt).contiguous();
    const int32_t mNum=(M+DEFAULT_BLOCK_M-1)/DEFAULT_BLOCK_M;
    const int32_t uc=std::min<int32_t>(DEFAULT_NUM_PHYSICAL_CORES,mNum);
    const int32_t tpc=(mNum+uc-1)/uc;
    at::Tensor y=at::empty({M}, x.options().dtype(at::kFloat));
    at::Tensor tc=at::empty({static_cast<long>(sizeof(XentKernelTiling))},at::device(at::kCPU).dtype(at::kByte));
    auto *t=reinterpret_cast<XentKernelTiling*>(tc.data_ptr());
    t->M=M; t->N=V; t->blockM=DEFAULT_BLOCK_M; t->usedCoreNum=uc; t->tasksPerCore=tpc;
    auto tn=tc.to(at::kPrivateUse1);
    auto stm=c10_npu::getCurrentNPUStream().stream(false);
    xent_do_fp16(uc,stm,
        static_cast<uint8_t*>(const_cast<void*>(x.storage().data())),
        static_cast<uint8_t*>(const_cast<void*>(tgt.storage().data())),
        static_cast<uint8_t*>(const_cast<void*>(y.storage().data())),
        static_cast<uint8_t*>(const_cast<void*>(tn.storage().data())));
    // Return per-token loss and mean loss
    return pybind11::make_tuple(y.mean(), y);
}}
PYBIND11_MODULE(_xent_ext, m) { m.def("run_cross_entropy_loss",&xent_ext::run_cross_entropy_loss,""); }

