#include "xent_kernel.h"
extern "C" __global__ __aicore__ void xent_custom_fp16(GM_ADDR x,GM_ADDR tgt,GM_ADDR y,GM_ADDR t){
    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIC_1_2); AscendC::TPipe p;
    XentKernel<half> k; k.Init(x,tgt,y,t,&p); k.Process();
}
extern "C" void xent_do_fp16(uint32_t d,void* s,uint8_t* x,uint8_t* tgt,uint8_t* y,uint8_t* t){
    xent_custom_fp16<<<d,nullptr,s>>>(x,tgt,y,t);
}

