#pragma once
#ifndef XENT_KERNEL_H
#define XENT_KERNEL_H
#include "kernel_operator.h"
#include "kernel_common.h"
#include "xent_tiling.h"
constexpr int32_t XENT_CHUNK = 64;

template <typename T>
class XentKernel {
public:
    __aicore__ inline void Init(GM_ADDR x, GM_ADDR target, GM_ADDR y, GM_ADDR tilingGM, AscendC::TPipe *pipe) {
        CopyTiling(&tiling_, tilingGM);
        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(x), tiling_.M * tiling_.N);
        tgtGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(target), tiling_.M);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(y), tiling_.M);
        if ASCEND_IS_AIV {
            pipe_ = pipe; subBlockRows_ = tiling_.blockM / AscendC::GetSubBlockNum();
            pipe_->InitBuffer(chunkQ_, 1, XENT_CHUNK * sizeof(T));
            pipe_->InitBuffer(wF_, XENT_CHUNK * sizeof(float));
            pipe_->InitBuffer(sBuf_, sizeof(float));
        }
    }
    __aicore__ inline void Process() {
        if ASCEND_IS_AIV {
            const int ci = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            const int si = AscendC::GetSubBlockIdx();
            for (int li = 0; li < tiling_.tasksPerCore; ++li) {
                const int bx = ci * tiling_.tasksPerCore + li;
                if (bx >= BlockCount()) continue;
                for (int r = 0; r < subBlockRows_; ++r) {
                    const int ri = bx * tiling_.blockM + si * subBlockRows_ + r;
                    if (ri < tiling_.M) ProcessRow(ri);
                }
            }
        }
    }
private:
    __aicore__ inline int32_t BlockCount() const { return (tiling_.M + tiling_.blockM - 1) / tiling_.blockM; }

    __aicore__ inline void ProcessRow(int32_t ri) {
        int32_t tgt = tgtGM_.GetValue(ri);
        float maxVal = -1.0e9f, xTgt = 0.0f;
        int32_t rowBase = ri * tiling_.N;

        // Pass 1: find max and x[target]
        for (int32_t start = 0; start < tiling_.N; start += XENT_CHUNK) {
            int32_t chunk = (start + XENT_CHUNK <= tiling_.N) ? XENT_CHUNK : (tiling_.N - start);
            chunkQ_.AllocTensor<T>(chunkL_);
            AscendC::DataCopy(chunkL_, xGM_[rowBase + start], chunk);
            chunkQ_.EnQue(chunkL_);
            chunkQ_.DeQue<T>(chunkL_);
            auto xFp32 = wF_.Get<float>();
            AscendC::Cast(xFp32, chunkL_, AscendC::RoundMode::CAST_NONE, chunk);
            AscendC::PipeBarrier<PIPE_V>();
            for (int32_t i = 0; i < chunk; ++i) {
                float v = xFp32(i);
                if (v > maxVal) maxVal = v;
                if (start + i == tgt) xTgt = v;
            }
            chunkQ_.FreeTensor(chunkL_);
        }

        // Pass 2: sum(exp(x - max))
        float sumVal = 0.0f;
        for (int32_t start = 0; start < tiling_.N; start += XENT_CHUNK) {
            int32_t chunk = (start + XENT_CHUNK <= tiling_.N) ? XENT_CHUNK : (tiling_.N - start);
            chunkQ_.AllocTensor<T>(chunkL_);
            AscendC::DataCopy(chunkL_, xGM_[rowBase + start], chunk);
            chunkQ_.EnQue(chunkL_);
            chunkQ_.DeQue<T>(chunkL_);
            auto xFp32 = wF_.Get<float>();
            AscendC::Cast(xFp32, chunkL_, AscendC::RoundMode::CAST_NONE, chunk);
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::Adds(xFp32, xFp32, -maxVal, chunk);
            AscendC::Exp(xFp32, xFp32, chunk);
            AscendC::PipeBarrier<PIPE_V>();
            for (int32_t i = 0; i < chunk; ++i) sumVal += xFp32(i);
            chunkQ_.FreeTensor(chunkL_);
        }

        auto s = sBuf_.Get<float>();
        s(0) = sumVal;
        AscendC::Ln(s, s, 1);
        yGM_.SetValue(ri, s(0) + maxVal - xTgt);
    }
private:
    XentKernelTiling tiling_{}; AscendC::TPipe *pipe_{}; int subBlockRows_{};
    AscendC::GlobalTensor<T> xGM_;
    AscendC::GlobalTensor<int32_t> tgtGM_;
    AscendC::GlobalTensor<float> yGM_;
    AscendC::TQue<AscendC::TPosition::VECIN,0> chunkQ_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> wF_, sBuf_;
    AscendC::LocalTensor<T> chunkL_;
};
#endif
